import type { TermInput } from "@/lib/schema";

const asOf = "2026-09-04";
const W = (s: string) => `https://en.wikipedia.org/wiki/${s}`;
type T = Omit<TermInput, "kind" | "asOf">;
const t = (x: T): TermInput => ({ kind: "term", asOf, links: x.wikipedia ? [{ label: "Wikipedia", url: x.wikipedia }] : undefined, ...x });

export const terms: TermInput[] = [
  // ---- ADC vocabulary ----
  t({ id: "payload", name: "Payload (ADC)", category: "ADC", tldr: "The payload is the poison an ADC carries, usually a chemotherapy far too toxic to give on its own.", summary: "The payload is the cytotoxic warhead conjugated to the antibody. Classes: tubulin inhibitors (MMAE, MMAF, DM1, DM4), topoisomerase-I inhibitors (DXd, SN-38, exatecan, belotecan derivatives), DNA-damaging agents (PBD dimers, calicheamicin, duocarmycin). Newer payloads: degraders, immune agonists, radionuclides. Membrane permeability determines bystander killing.", wikipedia: W("Antibody-drug_conjugate"), technologies: ["adc", "topoisomerase-inhibitors"] }),
  t({ id: "linker", name: "Linker (ADC)", category: "ADC", tldr: "The linker is the chemical tether between antibody and payload. It must hold in the blood and let go inside the tumour.", summary: "Cleavable linkers (protease-sensitive peptides like Val-Cit or GGFG, acid-labile hydrazones, glutathione-sensitive disulfides) release free payload; non-cleavable linkers (SMCC in T-DM1) release payload still attached to an amino acid, which cannot cross membranes. Linker hydrophilicity permits high DAR without aggregation.", wikipedia: W("Antibody-drug_conjugate"), technologies: ["adc", "site-specific-conjugation"] }),
  t({ id: "dar", wikipedia: W("Antibody-drug_conjugate"), aka: ["drug-to-antibody ratios"], name: "Drug-to-antibody ratio (DAR)", category: "ADC", tldr: "The drug-to-antibody ratio (DAR) is how many payload molecules ride on each antibody, typically 2 to 8.", summary: "The drug-to-antibody ratio, or DAR, is the number of payload molecules attached to each antibody in an antibody-drug conjugate, typically between 2 and 8. A higher DAR delivers more drug per binding event, as with T-DXd at roughly 8 and sacituzumab at about 7.6, but it increases hydrophobicity, aggregation and clearance unless hydrophilic linkers compensate. Site-specific conjugation gives a homogeneous DAR, which improves pharmacokinetics. The term belongs to the Antibody-drug conjugate (ADC) and Site-specific conjugation & linker chemistry technologies, is picked up by the Hydrophilic next-generation linkers term, and appears in the DESTINY-Breast03 paper and the idea on ADC dose and schedule optimisation trials.", technologies: ["adc", "site-specific-conjugation"] }),
  t({ id: "bystander-effect", wikipedia: W("Antibody-drug_conjugate"), links: [{ label: "Ogitani et al., Bystander killing effect of DS-8201a, a HER2-targeting antibody-drug conjugate (Cancer Science 2016)", url: "https://doi.org/10.1111/cas.12966" }], name: "Bystander effect (ADC)", category: "ADC", tldr: "When a released payload leaks out of the targeted cell and kills its neighbours, including cells that lack the target.", summary: "In an antibody-drug conjugate, the bystander effect is what happens when the released payload leaks out of the targeted cell and kills neighbouring cells, including cells that lack the target. It requires a cleavable linker and a membrane-permeable payload such as DXd, MMAE or SN-38. This explains why Trastuzumab deruxtecan works in HER2-low tumours while T-DM1, whose payload is not permeable, does not, and the same leakage is a source of toxicity to adjacent normal tissue. The concept is linked to the Antibody-drug conjugate (ADC) and Topoisomerase-I inhibitors technologies and to the payload terms DXd, MMAE and MMAF, and readers also meet it in the Sacituzumab govitecan and Polatuzumab vedotin entries and the DESTINY-Breast03 and DESTINY-Breast04 papers.", technologies: ["adc", "topoisomerase-inhibitors"], drugs: ["trastuzumab-deruxtecan"] }),
  t({ id: "ild", name: "Interstitial lung disease (ILD) / pneumonitis", category: "Toxicity", tldr: "Interstitial lung disease (ILD) is lung inflammation, a serious side effect of some ADCs (especially Enhertu) and immunotherapy.", summary: "Occurs in ~10-15% of T-DXd patients (grade 5 in ~1%); also with Dato-DXd, HER3-DXd, checkpoint inhibitors, and mTOR inhibitors. Requires monitoring, prompt steroids, and permanent discontinuation for grade ≥2 with T-DXd. Mechanism with DXd is incompletely understood (alveolar macrophage uptake proposed).", wikipedia: W("Interstitial_lung_disease"), drugs: ["trastuzumab-deruxtecan", "datopotamab-deruxtecan"] }),
  t({ id: "efflux-pump", name: "Drug efflux pumps (ABC transporters)", category: "Resistance", tldr: "Molecular pumps on cancer cells that eject chemotherapy and ADC payloads before they can act.", summary: "Drug efflux pumps are ABC transporters on cancer cells that eject chemotherapy and ADC payloads before they can act. The main ones are ABCB1 (P-glycoprotein or MDR1), ABCG2 (BCRP) and ABCC1 (MRP1), with substrates including taxanes, anthracyclines, MMAE, DXd and, for ABCG2, SN-38. They are upregulated in mesenchymal and stem-like states, hence the term's place in the Epithelial-mesenchymal transition & drug efflux pathway; some newer payloads and radiation are efflux-independent, whereas pump inhibitors failed clinically because of toxicity. It is linked to the Antibody-drug conjugate (ADC) and Cytotoxic chemotherapy technologies, to the bottleneck Acquired resistance to every therapy, and to ideas on payload-class switching and efflux-agnostic therapy for mesenchymal TNBC.", wikipedia: W("P-glycoprotein"), pathways: ["emt"], technologies: ["adc", "cytotoxic-chemotherapy"] }),
  t({ id: "resistance", aka: ["acquired resistance", "primary resistance", "adaptive resistance", "pre-existing resistance", "resistance mechanism", "resistance mechanisms", "resistant clone", "resistant clones", "resistant subclone", "resistant subclones", "bypass pathways", "bypass signalling", "bypass resistance", "chemoresistance", "chemoresistant", "chemotherapy resistance", "TKI resistance", "TKI-resistant", "drug-resistant", "therapy-resistant", "become resistant", "becomes resistant", "escape mechanism", "escape mechanisms", "escape mutation", "escape mutations", "reversion mutations", "BRCA reversion", "on-target mutations", "compound resistance mutations", "confers resistance", "emergence of resistance", "overcome resistance", "resistance alteration", "resistance pathway", "resistant disease"], name: "Drug resistance (primary and acquired)", category: "Resistance", tldr: "Why cancer drugs stop working: the tumour either never depended on the target or evolves around the block.", summary: "Primary: no target dependence, poor drug penetration, pre-existing resistant clones. Acquired: on-target mutations (EGFR T790M/C797S, ESR1, BRCA reversion, ALK G1202R), bypass signalling (MET amplification), lineage change (SCLC transformation), antigen loss (CD19-negative relapse), efflux, epigenetic plasticity. Tumours are evolving populations; combination and sequential strategies are the response.", wikipedia: W("Drug_resistance"), technologies: ["kinase-inhibitors", "liquid-biopsy"] }),

  // ---- Trial endpoints & stats ----
  t({ id: "orr", aka: ["objective response", "objective responses", "objective response rates", "overall response rate", "overall response", "confirmed responses", "radiographic response", "radiological response"], name: "Objective response rate (ORR)", category: "Endpoints", tldr: "Objective response rate (ORR) is the percentage of patients whose tumours shrink by at least 30%.", summary: "Objective response rate (ORR) is an endpoint recording the proportion of patients whose tumours shrink enough on scans to count as a response. Under RECIST 1.1 it combines complete and partial responses, and its aliases include overall response rate, confirmed responses and radiographic or radiological response. ORR is the basis for many accelerated approvals yet an imperfect surrogate for survival, which is why it appears in the bottleneck on trial design, endpoints and cost and in ideas on an independent programme to validate surrogate endpoints and on requiring a randomised phase 2 before any phase 3. The term is also used by Blinded independent central review (BICR), by the Sarcomas and EPCORE NHL-1 entries, and in the ASCENT, DeLLphi-301 and CodeBreaK 200 papers.", wikipedia: W("Response_evaluation_criteria_in_solid_tumors"), terms: ["recist"], related: ["recist", "duration-of-response-term", "single-arm", "basket-trial", "surrogate-validation", "surrogate-endpoint", "accelerated-approval", "bicr"], trials: ["navigate", "l-mind", "roar-atc", "announce", "atlantis"] }),
  t({ id: "recist", keyPapers: ["paper-therasse-recist-jnci-2000"], aka: ["RECIST 1.1", "measurable disease", "new lesion", "new lesions", "sum of longest diameters", "30% decrease", "≥30% decrease", "20% increase", "≥20% increase", "30% reduction", "RANO", "mRECIST", "PCWG3"], name: "RECIST", category: "Endpoints", tldr: "RECIST is the rulebook for measuring whether tumours have grown or shrunk on scans.", summary: "RECIST, the Response Evaluation Criteria in Solid Tumors 1.1, is the rulebook trials use to decide from scans whether tumours have grown or shrunk. It sums the longest diameters of up to five target lesions and sorts patients into complete response, partial response, stable disease or progressive disease, with a new lesion always counting as progression. The iRECIST variant adjusts for pseudoprogression on immunotherapy. RECIST does not capture metabolic or ctDNA response, a gap behind ideas on clonal clearance as an endpoint and ctDNA futility gates. It depends on the CT (computed tomography) and MRI technologies, underpins Objective response rate (ORR), and features in ideas on AI-assisted central imaging reads and structured radiology reports.", wikipedia: W("Response_evaluation_criteria_in_solid_tumors"), technologies: ["ct", "mri"], related: ["orr", "bicr", "pfs", "duration-of-response-term", "surrogate-validation"] }),
  t({ id: "pfs", aka: ["progression-free", "mPFS", "progression or death"], name: "Progression-free survival (PFS)", category: "Endpoints", tldr: "Progression-free survival (PFS) is how long patients live without their cancer growing.", summary: "Progression-free survival (PFS) measures the time from random assignment until the cancer progresses or the patient dies, whichever comes first. It is a common primary endpoint because a trial can read out with fewer patients and in less time than one powered for overall survival, but a PFS gain does not always translate into an OS benefit, as TROPION-Breast01 illustrated; PFS2 tracks progression on the next therapy. PFS is referenced by the Small-cell lung cancer, Sarcomas and Hodgkin lymphoma entries, the POLARIX trial and Michael LeBlanc, and it features in the bottlenecks on trial design, real-world evidence and quality of life. Ideas engaging with it include clonal clearance as an endpoint, a six-week ctDNA switch and seamless phase 2/3 designs with pre-registered go rules.", wikipedia: W("Progression-free_survival"), related: ["os", "surrogate-endpoint", "surrogate-validation", "crossover", "recist", "bicr", "kaplan-meier-curve", "hazard-ratio", "estimand", "trial-failure-modes"], trials: ["tropion-breast01", "codebreak-200", "checkmate-9er"] }),
  t({ id: "os", aka: ["OS", "overall-survival", "mOS", "survival benefit", "survival advantage", "survival detriment", "live longer", "lived longer", "longer survival", "death from any cause"], name: "Overall survival (OS)", category: "Endpoints", tldr: "Overall survival (OS) is how long patients live, full stop. It is the gold-standard endpoint.", summary: "Overall survival (OS) is the time from random assignment to death from any cause, and it remains the gold-standard endpoint in oncology trials. Its interpretation is confounded by crossover and by therapies given after progression, and it requires long follow-up. Regulators increasingly want to see that OS is not harmed even when PFS is the primary endpoint. The term is cited by the Small-cell lung cancer and Hodgkin lymphoma entries, the ZUMA-7 trial and Michael LeBlanc, and it runs through the bottlenecks on trial design, weak real-world evidence, patient voice and quality of life. Related ideas include randomising the next line of treatment before the first fails, a regulatory endpoint for antimetastatic drugs and seamless phase 2/3 trials with pre-registered go rules.", wikipedia: W("Survival_rate"), related: ["pfs", "crossover", "surrogate-validation", "kaplan-meier-curve", "hazard-ratio", "median-survival", "landmark-survival", "quality-adjusted-survival", "absolute-benefit", "estimand"], trials: ["checkmate-067", "adaura", "tropion-breast01", "keynote-564"] }),
  t({ id: "efs", aka: ["EFS", "DFS", "iDFS", "RFS", "event-free survival", "recurrence-free survival", "recurrence-free", "relapse-free survival", "relapse-free", "invasive disease-free survival", "distant disease-free survival", "distant recurrence-free", "failure-free survival", "time to recurrence"], wikipedia: "https://en.wikipedia.org/wiki/Disease-free_survival", name: "Event-free / disease-free survival (EFS, DFS, iDFS, RFS)", category: "Endpoints", tldr: "In early-stage cancer: how long patients stay free of recurrence, progression, or death.", summary: "Event-free survival and its relatives, disease-free survival, invasive disease-free survival and recurrence-free survival, are the endpoints used in early-stage cancer to measure how long patients stay free of recurrence, progression or death. Event definitions differ by trial: EFS in KEYNOTE-522 counts progression that precludes surgery, iDFS in monarchE and NATALEE counts invasive recurrence, second cancers and death, and RFS is the measure in INTerpath-001 (V940-001). These endpoints are accepted surrogates for adjuvant approvals. They appear in the NADINA, KEYNOTE-716, KEYNOTE-689, MATTERHORN, ZUMA-7, ASCENT-05 / OptimICE-RD and TROPION-Breast03 trial records, in the Neuroblastoma (paediatric) entry and in the KEYNOTE-522 and CheckMate 816 papers.", trials: ["keynote-522", "natalee", "interpath-001", "monarche", "keynote-564", "adaura", "challenge"], related: ["surrogate-validation", "surrogate-endpoint", "pcr", "mrd", "os", "group-sequential-design", "absolute-benefit"] }),
  t({ id: "hazard-ratio", aka: ["HR 0", "HR 1", "HR of", "HR for death", "HR for progression", "HR for recurrence", "HRs", "Cox proportional hazards", "proportional hazards"], name: "Hazard ratio (HR)", category: "Endpoints", tldr: "A hazard ratio is a number comparing the rate of bad events in two groups. An HR of 0.5 means the risk is halved at any moment.", summary: "The hazard ratio (HR) is a single number comparing the rate of bad events, such as death or progression, between two groups in a trial; an HR of one half means the risk is halved at any given moment. It comes from Cox proportional hazards models, an HR below 1 favours the experimental arm, and a confidence interval excluding 1 indicates statistical significance. The HR says nothing about absolute benefit or how long it lasts, so it features in ideas on powering trials for a benefit patients would value, crossover-adjusted survival and Bayesian shrinkage for subgroup claims. The term is referenced by the Pancreatic ductal adenocarcinoma entry, Michael LeBlanc, the bottlenecks on trial design and trial diversity, and ideas on Bayesian borrowing and a rulebook for external control arms.", wikipedia: W("Hazard_ratio"), related: ["hazard-ratio-basics", "confidence-interval", "p-value", "kaplan-meier-curve", "absolute-benefit", "os", "pfs", "crossover", "sample-size-re-estimation"], trials: ["checkmate-067", "adaura", "challenge"] }),
  t({ id: "pcr", links: [{ label: "ClinicalTrials.gov NCT03036488: KEYNOTE-522", url: "https://clinicaltrials.gov/study/NCT03036488" }, { label: "ClinicalTrials.gov NCT05812807: OptimICE-pCR (A012103)", url: "https://clinicaltrials.gov/study/NCT05812807" }], aka: ["pathological complete response", "ypT0", "ypN0", "non-pCR", "residual invasive disease", "residual disease after neoadjuvant"], name: "Pathologic complete response (pCR)", category: "Endpoints", tldr: "No invasive cancer left in the breast and lymph nodes when the surgeon removes the tissue after pre-surgery treatment.", summary: "Pathologic complete response (pCR) means that no invasive cancer remains in the breast and lymph nodes when the surgeon removes tissue after pre-surgery treatment, recorded as ypT0/is ypN0. It is strongly prognostic in Triple-negative breast cancer (TNBC) and HER2-positive breast cancer and is accepted for accelerated approval of neoadjuvant regimens, as in KEYNOTE-522. Trials now use it as a decision point: OptimICE-pCR (A012103) tests de-escalating therapy after pCR, while other studies escalate treatment for residual disease. The term is cited by the Oesophageal and Bladder & urothelial cancer entries, by CheckMate 816, KATHERINE, PHERGain, NICHE-2 and MATTERHORN, and by the related terms Major pathological response (MPR) and Clinical complete response (cCR).", cancers: ["tnbc", "breast-her2-positive"], trials: ["keynote-522", "optimice-pcr"], related: ["surrogate-validation", "surrogate-endpoint", "efs", "window-of-opportunity-trial", "neoadjuvant-adjuvant", "response-adaptive-randomisation"] }),
  t({ id: "rcb", links: [{ label: "Residual cancer burden index (Symmans et al., J Clin Oncol 2007)", url: "https://doi.org/10.1200/JCO.2007.10.6823" }], name: "Residual cancer burden (RCB)", category: "Endpoints", tldr: "A pathology score for how much cancer remains in the breast and lymph nodes after pre-surgery treatment, from 0 (none) to III (a large amount), combining tumour bed size, cellularity and nodal involvement. RCB-II or III after neoadjuvant therapy predicts a high risk of relapse and defines who enters escalation trials.", summary: "Residual cancer burden (RCB) is a score for how much cancer is left after pre-surgery treatment, running from 0 for none to III for a large amount. The index, developed at MD Anderson Cancer Center, combines tumour bed size, cellularity and nodal involvement, and an RCB-II or RCB-III result after neoadjuvant therapy predicts a high risk of relapse and defines populations for escalation trials, including ctDNA-guided and ADC-based post-neoadjuvant therapy. In this corpus it is attached to Triple-negative breast cancer (TNBC) and is used by the ASCENT-05 / OptimICE-RD and TROPION-Breast03 trials, by Laura J. Esserman, and by an idea on an ADC for residual disease after KEYNOTE-522. The KEYNOTE-522, OlympiA and KATHERINE papers also refer to it.", cancers: ["tnbc"] }),
  t({ id: "ppv", name: "Positive predictive value (PPV)", category: "Diagnostics", tldr: "Positive predictive value (PPV) is the chance that a positive test result is actually right: true positives divided by all positives. Because it falls as a disease becomes rarer, even a specific screening test gives mostly false alarms when prevalence is low, which is why PPV decides whether a multi-cancer blood test is useful.", summary: "Positive predictive value (PPV) is the probability that a test result saying 'cancer' is actually correct. It is true positives divided by all positives, so it depends heavily on how common the disease is in the tested population: even a highly specific screening test yields many false alarms when prevalence is low. This makes PPV central to judging Multi-cancer early detection (MCED) tests such as Galleri, and it recurs in the PATHFINDER 2 trial, the early detection roadmap, and the bottlenecks on cancers found late and on overdiagnosis and false alarms. It is also cited by Breath and volatile-organic-compound detection, Harbinger Health, and ideas on a national pathway for people with a positive multi-cancer blood test and urine DNA triage for haematuria.", wikipedia: W("Positive_and_negative_predictive_values"), technologies: ["mced"] }),
  t({ id: "stage-shift", wikipedia: W("Cancer_staging"), name: "Stage shift", category: "Diagnostics", tldr: "Stage shift means finding more cancers early and fewer late; it is the measurable goal of screening.", summary: "Stage shift is the observable goal of screening: more cancers found at an early stage and fewer found late. It is the primary endpoint of the NHS-Galleri trial, defined as a reduction in the incidence of stage III and IV disease. A stage shift does not by itself prove that a screening test saves lives, because lead-time bias, length-time bias and overdiagnosis can all produce one, but it is a necessary precondition for any such benefit. The term is linked to the Multi-cancer early detection (MCED) and Mammography & tomosynthesis technologies and is referenced by UKCTOCS, High-risk pancreatic surveillance, the early detection roadmap, the bottleneck on late-found cancers and an idea on letting MCED trials read out on late-stage incidence.", technologies: ["mced", "mammography"], trials: ["nhs-galleri"] }),
  t({ id: "suv", name: "Standardised uptake value (SUV)", category: "Imaging", tldr: "The standardised uptake value (SUV) is a number for how brightly a spot lights up on a PET scan.", summary: "The standardised uptake value (SUV) is the number radiologists use to say how brightly a spot lights up on a PET scan. It is tissue radioactivity normalised to the injected dose and body weight, and SUVmax is the most widely used version. Values are affected by the scanner, the uptake time and blood glucose, and the PERCIST response criteria use SUL, a lean-body variant, instead. The term belongs to the PET (positron emission tomography) and FDG PET technology entries and to the Fludeoxyglucose F-18 (FDG) drug record, and it is referenced by the Cancer metabolism pathway, the Warburg effect, the Society of Nuclear Medicine and Molecular Imaging, and ideas on de-acidifying tumours so T cells can work and on a phase 0 fund using microdoses and imaging.", wikipedia: W("Standardized_uptake_value"), technologies: ["pet", "fdg-pet"] }),

  // ---- Biomarkers ----
  t({ id: "ihc", aka: ["0/1+", "1+/2+", "2+/3+", "membrane staining", "membranous staining", "staining intensity"], name: "Immunohistochemistry (IHC)", category: "Diagnostics", tldr: "Staining a tissue slice with antibodies so a protein shows up in colour under the microscope.", summary: "Immunohistochemistry (IHC) stains a thin slice of tissue with antibodies so that a chosen protein shows up in colour under the microscope. Scoring is semi-quantitative, from 0 through 1+ and 2+ to 3+, and it is the basis of ER, PR, HER2 and PD-L1 testing. Results suffer from pre-analytic variability and inter-observer disagreement, especially at the low end where HER2 0 must be told from 1+, and AI quantification is improving reproducibility. The term is tied to the Histopathology & immunohistochemistry and Digital pathology & AI technologies and to the bottleneck on unvalidated biomarkers, and ideas that build on it include AI quantification of HER2-low and calibrated reference slides for HER2-low scoring. It features in the DESTINY-Breast04, DESTINY-Breast06 and SPOTLIGHT papers.", wikipedia: W("Immunohistochemistry"), technologies: ["histopathology-ihc", "digital-pathology-ai"] }),
  t({ id: "her2-low", wikipedia: W("HER2"), links: [{ label: "NCI Dictionary of Cancer Terms: HER2-low breast cancer", url: "https://www.cancer.gov/publications/dictionaries/cancer-terms/def/her2-low-breast-cancer" }], name: "HER2-low and HER2-ultralow", category: "Biomarkers", tldr: "Tumours with a little HER2 (IHC 1+ or 2+ without amplification), or a trace (ultralow), which older HER2 drugs ignored but Enhertu can attack.", summary: "HER2-low describes tumours with a little HER2, scored IHC 1+ or 2+ without gene amplification, and HER2-ultralow describes a trace, scored IHC 0 with faint membrane staining in a small fraction of cells. Older HER2 drugs ignored these tumours, but Trastuzumab deruxtecan can attack them, as DESTINY-Breast04 and DESTINY-Breast06 showed in HR-positive / HER2-negative breast cancer and Triple-negative breast cancer (TNBC). The result redefined what 'HER2-negative' means and put pressure on pathology to score the low end reliably, hence the links to Histopathology & immunohistochemistry, Companion diagnostics, the pairing HER2-low scoring to T-DXd and the idea on AI quantification of HER2-low. It also appears in the bottleneck on biomarker validation and the Giuseppe Curigliano entry.", drugs: ["trastuzumab-deruxtecan"], trials: ["destiny-breast04", "destiny-breast06"], cancers: ["tnbc", "breast-hr-positive"] }),
  t({ id: "cps", wikipedia: W("PD-L1"), name: "Combined positive score (CPS)", category: "Biomarkers", tldr: "A PD-L1 score that counts stained tumour cells and immune cells together.", summary: "The combined positive score (CPS) is a PD-L1 measure that counts stained tumour cells together with stained lymphocytes and macrophages, divides by the number of viable tumour cells and multiplies by 100, using the 22C3 assay. A CPS of 10 or more defines Pembrolizumab eligibility in Triple-negative breast cancer (TNBC) under KEYNOTE-355, while a CPS of 1 or more is the threshold in head and neck, gastric and cervical cancers. It differs from the Tumour proportion score (TPS), which counts tumour cells only, and from the SP142 immune-cell score used for atezolizumab. The score is attached to the PD-L1 target and is referenced by the Gastric, Oesophageal, Ovarian, Cervical and Head and neck cancer entries and by the KEYNOTE-048, KEYNOTE-689, KEYNOTE-590, KEYNOTE-859 and CheckMate 649 trials.", targets: ["pdl1"], drugs: ["pembrolizumab"], trials: ["keynote-355"] }),
  t({ id: "tils", aka: ["tumor-infiltrating lymphocytes", "tumour-infiltrating lymphocyte"], name: "Tumour-infiltrating lymphocytes (TILs)", category: "Biomarkers", tldr: "Immune cells that have got inside the tumour. More of them means better outcomes in triple-negative breast cancer.", summary: "Tumour-infiltrating lymphocytes (TILs) are immune cells that have got inside the tumour, and in Triple-negative breast cancer (TNBC) more of them means better outcomes. Stromal TILs are scored on ordinary H&E slides by the International TILs Working Group method, and their strong prognostic signal in stage I disease has driven de-escalation trials, captured in the idea on TIL-based omission of chemotherapy in stage I TNBC. TILs are also the raw material for TIL therapy, so the term links to that technology and to Digital pathology & AI. It is referenced by Histopathology & immunohistochemistry, Spatial-omics-guided treatment selection, the TNBC roadmap, Carsten Denkert and Sherene Loi, and by the bottlenecks on cold tumours and on predicting immunotherapy response.", wikipedia: W("Tumor-infiltrating_lymphocytes"), cancers: ["tnbc"], technologies: ["til-therapy", "digital-pathology-ai"] }),
  t({ id: "tmb", name: "Tumour mutational burden (TMB)", category: "Biomarkers", tldr: "How many mutations a tumour has. More mutations mean more targets for the immune system.", summary: "Tumour mutational burden (TMB) counts how many mutations a tumour carries, expressed as mutations per megabase from panel or exome sequencing, on the logic that more mutations mean more targets for the immune system. A TMB of 10 mutations per megabase or higher is a tumour-agnostic indication for Pembrolizumab, established in KEYNOTE-158. It is an imperfect predictor and varies from panel to panel, which is why the idea of a single calibrated TMB across all sequencing panels exists and why the term features in the bottleneck on unvalidated biomarkers. TMB is linked to Comprehensive genomic profiling and Immune checkpoint inhibitors, to the Antigen presentation & immune editing pathway, and to Aurélien Marabelle, Ramaswamy Govindan and Timothy A. Chan.", wikipedia: W("Tumor_mutational_burden"), technologies: ["cgp"], drugs: ["pembrolizumab"] }),
  t({ id: "msi", name: "Microsatellite instability (MSI-H) / mismatch repair deficiency (dMMR)", category: "Biomarkers", tldr: "Microsatellite instability is the mark of a broken DNA spell-checker (loss of MLH1, MSH2, MSH6 or PMS2) that leaves thousands of mutations, so the tumour displays abnormal proteins that T cells can recognise. It is found in a fraction of colorectal and endometrial cancers and was the basis of the first tumour-agnostic approval, pembrolizumab in 2017.", summary: "Microsatellite instability (MSI-H), or mismatch repair deficiency (dMMR), is the mark of a broken DNA spell-checker: loss of MLH1, MSH2, MSH6 or PMS2, through Lynch syndrome or sporadic MLH1 methylation, creates thousands of mutations and makes the tumour recognisable to T cells and therefore responsive to immunotherapy. It is found in a meaningful fraction of Colorectal cancer and Endometrial cancer. Pembrolizumab in MSI-H disease was the first tumour-agnostic approval, in 2017, and Dostarlimab achieves complete responses in dMMR rectal cancer without surgery. The biomarker is central to the KEYNOTE-177, CheckMate 8HW, NICHE-2, ATOMIC, AZUR-1 and RUBY trials and to the pairing of neoadjuvant checkpoint inhibitor with surgery or no surgery in dMMR colorectal cancer.", wikipedia: W("Microsatellite_instability"), drugs: ["pembrolizumab", "dostarlimab"], cancers: ["colorectal", "endometrial"] }),
  t({ id: "hrd", name: "Homologous recombination deficiency (HRD)", category: "Biomarkers", tldr: "A tumour that cannot properly repair double-strand DNA breaks, usually because of BRCA or related gene loss.", summary: "Homologous recombination deficiency (HRD) describes a tumour that cannot properly repair double-strand DNA breaks, usually because BRCA1, BRCA2 or a related gene has been lost. It is detected by a BRCA1/2 mutation or by genomic-scar scores such as the myChoice CDx GIS at a threshold of 42 or FoundationOne LOH, and it predicts benefit from PARP inhibitors and platinum. HRD is common in high-grade serous ovarian cancer and present in a substantial minority of Triple-negative breast cancer (TNBC). The term sits with the HRD & BRCA testing technology and the BRCA1 / BRCA2 (HRD) and PARP targets, and it is used by the PRIMA and PAOLA-1 trials, Rucaparib, the pairing of PARP inhibitor plus bevacizumab maintenance, Sabine Linn and the bottleneck on biomarker validation.", wikipedia: W("Homologous_recombination"), targets: ["brca", "parp"], technologies: ["hrd-testing"] }),
  t({ id: "ctdna", aka: ["circulating tumor DNA", "ctDNA-positive", "ctDNA-negative", "ctDNA-based", "ctDNA-directed", "tumour fraction"], name: "Circulating tumour DNA (ctDNA)", category: "Biomarkers", tldr: "Circulating tumour DNA (ctDNA) consists of fragments of DNA shed by tumour cells into the blood, detectable with sensitive sequencing.", summary: "Circulating tumour DNA (ctDNA) is made up of DNA fragments shed by tumour cells into the bloodstream, where they form only a small fraction of all cell-free DNA and are detected with sensitive sequencing. Its uses span genotyping for companion diagnostics, tracking resistance mutations such as EGFR T790M and ESR1, molecular residual disease, early detection and response monitoring. Shedding varies with tumour type and burden, and clonal haematopoiesis can confound results. The term underpins the Liquid biopsy (ctDNA), MRD / molecular residual disease testing and Multi-cancer early detection (MCED) technologies, and it appears in the SERENA-6, CIRCULATE-Japan and IMvigor011 trials and in ideas on molecular-progression switching beyond ESR1 and HPV ctDNA to guide cervical cancer therapy.", wikipedia: W("Circulating_tumor_DNA"), technologies: ["liquid-biopsy", "mrd-testing", "mced"] }),
  t({ id: "mrd", aka: ["MRD-directed", "MRD-negativity", "measurable residual disease", "minimal residual disease", "molecular remission"], name: "Minimal / molecular residual disease (MRD)", category: "Biomarkers", tldr: "Cancer still present after treatment but too small to see on scans, detected by blood or marrow tests.", summary: "Minimal or molecular residual disease (MRD), also called measurable residual disease, is cancer that persists after treatment at a level too small to see on scans but detectable in blood or marrow; a negative result is called molecular remission. In leukaemia and myeloma it is measured by flow cytometry or NGS of marrow (clonoSEQ); in solid tumours it means ctDNA after surgery, covered under MRD / molecular residual disease testing. MRD positivity predicts relapse, MRD-guided escalation (IMvigor011) and de-escalation (DYNAMIC) are proven concepts, and MRD is an accepted endpoint in myeloma trials (FDA ODAC 2024). Readers meet it in the Colorectal, Pancreatic, Bladder & urothelial, DLBCL and Multiple myeloma entries and in CIRCULATE-Japan.", wikipedia: W("Minimal_residual_disease"), technologies: ["mrd-testing"], trials: ["imvigor011", "dynamic"] }),
  t({ id: "vaf", wikipedia: W("Allele_frequency"), links: [{ label: "Li et al., Standards and guidelines for the interpretation and reporting of sequence variants in cancer: AMP, ASCO and CAP joint consensus (Journal of Molecular Diagnostics 2017)", url: "https://doi.org/10.1016/j.jmoldx.2016.10.002" }], name: "Variant allele frequency (VAF)", category: "Genomics", tldr: "The fraction of DNA reads carrying a mutation. Tells you how much of the sample is mutant and how clonal it is.", summary: "Variant allele frequency (VAF) is the fraction of sequencing reads at a position that carry a given mutation, and it tells you how much of a sample is mutant and how clonal the mutation is. The value depends on tumour purity, copy number and clonality, so it must be read with those in mind. In ctDNA, VAF tracks tumour burden over time, and very low values require error-suppressed sequencing. The term is linked to Comprehensive genomic profiling and Liquid biopsy (ctDNA), to the Clonal evolution & minimal residual disease and Clonal haematopoiesis (CHIP) pathways, and to the bottleneck on tumour heterogeneity. Ideas built on it include a clone report from blood at every treatment cycle and truncal or branch labelling of mutations, and it features in the GALAXY paper.", technologies: ["cgp", "liquid-biopsy"] }),
  t({ id: "vus", name: "Variant of uncertain significance (VUS)", category: "Genomics", tldr: "A variant of uncertain significance (VUS) is a genetic change that has been found but nobody yet knows whether it matters.", summary: "A variant of uncertain significance (VUS) is a genetic change that has been detected but whose effect on disease is not yet known. Such findings are common on germline panels and in tumour sequencing, and they should not drive treatment decisions; over time many are reclassified through ClinVar, functional assays and population data. The term is linked to the Germline (hereditary) testing and Comprehensive genomic profiling technologies, to the ClinVar collection and AlphaMissense, and to the terms Mutation, Genomic profiling and Hereditary cancer syndromes. It appears in the bottleneck on unidentified inherited risk, and ideas that respond to it include testing every possible mutation in every cancer gene so no result is uncertain, and a plain-language version of every genomic report.", wikipedia: W("Variant_of_uncertain_significance"), technologies: ["germline-testing", "cgp"] }),
  t({ id: "ngs", name: "Next-generation sequencing (NGS)", category: "Genomics", tldr: "Reading millions of DNA fragments in parallel, the engine behind every modern genomic test.", summary: "Next-generation sequencing (NGS) reads millions of DNA fragments in parallel and is the engine behind every modern genomic test. Short-read instruments from Illumina dominate clinical practice, while long-read platforms from PacBio and Oxford Nanopore resolve structural variants and methylation. Panels, exomes, genomes and transcriptomes are all NGS applications, so the term underlies Comprehensive genomic profiling, Whole-exome & whole-genome sequencing and RNA sequencing & expression profiling, and it connects to the DNA term and the ALASCCA trial. It also appears in the bottleneck on data silos and in ideas on sequencing reports that list open matched trials, machine-readable genomic reports deposited nationally and reflex genomic profiling at diagnosis of advanced cancer.", wikipedia: W("DNA_sequencing"), technologies: ["cgp", "wes-wgs", "rna-seq"] }),
  t({ id: "gene-fusion", aka: ["gene fusions", "fusion gene", "fusion genes", "fusion-driven", "fusion-positive", "fusions", "oncogenic fusions", "rearrangement", "chromosomal translocation", "chromosomal rearrangements"], name: "Gene fusion", category: "Genomics", tldr: "A gene fusion is two genes broken and joined together, creating a hybrid protein that can drive cancer. Fusion-driven cancers are often exquisitely drug-sensitive.", summary: "A gene fusion joins two broken genes into one, producing a hybrid protein that can drive cancer, and fusion-driven cancers are often exquisitely drug-sensitive. Well-known examples include EML4-ALK, ROS1, RET, NTRK, FGFR2, NRG1 and BCR-ABL, and the ALK, RET, NTRK and FGFR2 targets are linked here. Fusions are best detected by RNA sequencing & expression profiling, define tumour-agnostic indications for NTRK and RET, and are the archetype of oncogene addiction. The term is cited by the Biliary tract cancer and Ewing sarcoma entries, by FGFR2 fusions and rearrangements, by Janet Rowley, Arul M. Chinnaiyan and Olivier Delattre, and by ideas on degraders for the fusion proteins that drive childhood sarcomas and a standard for tumour-agnostic approvals.", wikipedia: W("Fusion_gene"), targets: ["alk", "ret", "ntrk", "fgfr2"], technologies: ["rna-seq"] }),
  t({ id: "mutational-signature", aka: ["mutational signatures"], name: "Mutational signature", category: "Genomics", tldr: "A characteristic pattern of mutations that reveals what caused them: tobacco, UV, a broken repair gene.", summary: "A mutational signature is a characteristic pattern of mutations that reveals what caused them, whether tobacco, ultraviolet light or a broken repair gene. The COSMIC catalogue names them: SBS1 for ageing, SBS3 for HRD, SBS4 for tobacco, SBS7 for UV, SBS2 and SBS13 for APOBEC, and SBS6 and SBS15 for mismatch repair loss. Signature 3 identifies HRD beyond BRCA, and APOBEC signatures predict certain resistance mutations, which motivates ideas on APOBEC inhibitors during targeted therapy and on blocking error-prone repair. Signatures require Whole-exome & whole-genome sequencing, and the term links to the COSMIC collection, Gad Getz, the TCGA Pan-Cancer Atlas paper and the pathways on chromosomal instability and clonal evolution.", wikipedia: W("Mutational_signatures"), technologies: ["wes-wgs"] }),
  t({ id: "pam50", wikipedia: W("Breast_cancer_classification"), links: [{ label: "PAM50 intrinsic-subtype predictor (Parker et al., J Clin Oncol 2009)", url: "https://doi.org/10.1200/JCO.2008.18.1370" }], name: "PAM50 / intrinsic subtypes", category: "Genomics", tldr: "A 50-gene test that sorts breast cancers into luminal A, luminal B, HER2-enriched, and basal-like.", summary: "PAM50 is a 50-gene expression test that sorts breast cancers into the intrinsic subtypes luminal A, luminal B, HER2-enriched and basal-like. It derives from the molecular portraits of Perou and Sørlie and is commercialised as Prosigna. Basal-like largely overlaps with Triple-negative breast cancer (TNBC), HER2-enriched predicts response to HER2 blockade regardless of IHC, and the luminal subtypes matter for HR-positive / HER2-negative breast cancer. The test depends on RNA sequencing & expression profiling and is referenced by the TCGA Pan-Cancer Atlas paper, the organ tropism pathway on seed and soil, and an idea on omitting radiotherapy for very low-risk breast cancer. Institutions associated with it include UNC Lineberger Comprehensive Cancer Center and SOLTI Cancer Research Group.", technologies: ["rna-seq"], cancers: ["tnbc", "breast-hr-positive"] }),
  t({ id: "neoantigen", aka: ["neoantigens"], name: "Neoantigen", category: "Immunology", tldr: "A protein fragment created by a tumour mutation that the immune system has never seen before, so it can attack it without harming normal cells.", summary: "Arise from missense mutations, frameshifts, fusions, and splice variants; must be processed and presented on the patient's HLA. Predicted computationally (binding affinity, expression, clonality). The targets of personalised mRNA vaccines and neoantigen-specific TCR-T; higher TMB means more candidates.", wikipedia: W("Neoantigen"), technologies: ["neoantigen-mrna-vaccine", "tcr-t"], drugs: ["intismeran-autogene"] }),
  t({ id: "oncogene-addiction", name: "Oncogene addiction", category: "Biology", tldr: "When a cancer depends so completely on one mutated gene that blocking it collapses the tumour.", summary: "Oncogene addiction is the state in which a cancer depends so completely on a single mutated gene that blocking it collapses the tumour. The term was coined by Weinstein in 2002, and EGFR, ALK, BCR-ABL, KIT and BRAF V600E tumours exemplify it: dramatic responses to a single agent, followed by acquired resistance. It underlies the whole targeted-therapy paradigm and so is linked to the Small-molecule kinase inhibitors technology and the hallmark of sustaining proliferative signalling. Readers meet it in the Chronic myeloid leukaemia (CML) and Gastrointestinal stromal tumour (GIST) entries, the Gefitinib and Crizotinib drug records, the FLAURA and ADAURA papers, the entries for Brian Druker and Bud Romine, and ideas on molecular glues against MYC-MAX.", wikipedia: W("Oncogene_addiction"), technologies: ["kinase-inhibitors"] }),
  t({ id: "synthetic-lethality", name: "Synthetic lethality", category: "Biology", tldr: "Two genes where losing either alone is fine but losing both kills the cell. Cancers that have lost one become vulnerable to drugs against the other.", summary: "Synthetic lethality describes two genes where losing either alone is tolerated but losing both kills the cell, so a cancer that has lost one becomes vulnerable to a drug against the other. BRCA and PARP is the proven pair; others in development include MTAP/PRMT5, MSI/WRN, HRD/POLQ, TP53/WEE1, SMARCA4/SMARCA2 and ARID1A/EZH2, and CRISPR screens map such pairs systematically. The concept links to the Synthetic lethality approaches, PARP inhibitors and CRISPR functional genomics technologies and is cited by the Ovarian cancer and Mesothelioma entries, The Institute of Cancer Research and Christopher Lord. Ideas drawing on it include PRMT5/MAT2A lethality for MTAP-deleted mesothelioma, a WRN inhibitor programme and a synthetic lethality map for every cancer driver.", wikipedia: W("Synthetic_lethality"), technologies: ["synthetic-lethality-approaches", "parp-inhibitor", "crispr-screens"] }),

  // ---- Immunology / toxicity ----
  t({ id: "crs", name: "Cytokine release syndrome (CRS)", category: "Toxicity", tldr: "A flood of inflammatory signals when immune cells are activated en masse, causing fever, low blood pressure, and sometimes organ failure.", summary: "Cytokine release syndrome (CRS) is a flood of inflammatory signals released when immune cells are activated en masse, producing fever, low blood pressure and sometimes organ failure. It occurs with CAR-T cell therapy, T-cell engagers and some other bispecifics, is graded by ASTCT criteria and is managed with tocilizumab, which blocks the IL-6 receptor, and steroids. Step-up dosing and prophylactic tocilizumab reduce its incidence, and outpatient administration of bispecifics is now possible. The term is referenced by the Acute lymphoblastic leukaemia, Diffuse large B-cell lymphoma, Multiple myeloma and Small-cell lung cancer entries, by the drug records for Tisagenlecleucel, Lisocabtagene maraleucel, Epcoritamab, Xaluritamig and Pasritamig, and by the ELIANA trial.", wikipedia: W("Cytokine_release_syndrome"), technologies: ["car-t", "t-cell-engager"] }),
  t({ id: "icans", wikipedia: W("Cytokine_release_syndrome"), links: [{ label: "ASTCT consensus grading for CRS and ICANS (Lee et al., Biol Blood Marrow Transplant 2019)", url: "https://doi.org/10.1016/j.bbmt.2018.12.758" }], name: "ICANS (neurotoxicity)", category: "Toxicity", tldr: "ICANS is confusion, speech difficulty, and rarely seizures after CAR-T or bispecific therapy.", summary: "ICANS, the immune effector cell-associated neurotoxicity syndrome, is the confusion, speech difficulty and occasionally seizures that can follow CAR-T cell therapy or bispecific T-cell engagers. It is more common with CD28-costimulated CAR-T products and is managed with steroids, and a delayed parkinsonism has been seen rarely with BCMA-directed CAR-T such as cilta-cel. The term appears in the Acute lymphoblastic leukaemia, Diffuse large B-cell lymphoma and Multiple myeloma entries and in the drug records for Tisagenlecleucel, Obecabtagene autoleucel, Lisocabtagene maraleucel, Idecabtagene vicleucel and Epcoritamab. It also features in the bottlenecks on toxicity and the limits of the patient, on manufacturing living medicines, and on toxicity and quality of life being undervalued.", technologies: ["car-t", "t-cell-engager"] }),
  t({ id: "irae", links: [{ label: "Haanen et al., Management of toxicities from immunotherapy: ESMO Clinical Practice Guideline (Annals of Oncology 2022)", url: "https://doi.org/10.1016/j.annonc.2022.10.001" }], aka: ["immune-related adverse event"], name: "Immune-related adverse events (irAEs)", category: "Toxicity", tldr: "Immune-related adverse events (irAEs) are the autoimmune side effects of checkpoint inhibitors: colitis, thyroid problems, rash, hepatitis, pneumonitis.", summary: "Immune-related adverse events (irAEs) are the autoimmune side effects of Immune checkpoint inhibitors, including colitis, thyroid problems, rash, hepatitis and pneumonitis. Any organ can be affected, and they are most frequent and most severe when CTLA-4 and PD-1 blockade are combined. Management relies on steroids and biologics; some irAEs, notably the endocrinopathies, are permanent, and their occurrence correlates only weakly with response. The term is cited by the Melanoma and Mesothelioma entries and the drug records for Toripalimab, Tislelizumab and Camrelizumab, by the bottlenecks on toxicity and on predicting immunotherapy response, and by ideas on testing drugs in old and unhealthy animals and reading the immune response in blood three weeks in.", technologies: ["checkpoint-inhibitor"] }),
  t({ id: "abscopal-effect", aka: ["abscopal effects"], name: "Abscopal effect", category: "Immunology", tldr: "When irradiating one tumour causes untreated tumours elsewhere to shrink, via the immune system.", summary: "The abscopal effect is the phenomenon in which irradiating one tumour causes untreated tumours elsewhere in the body to shrink, mediated by the immune system. It is rare with radiotherapy alone and more frequent when combined with Immune checkpoint inhibitors, and the mechanism runs through cGAS-STING innate sensing, antigen release and T-cell priming. It is the rationale for trials of SBRT / SABR (stereotactic radiotherapy) plus immunotherapy, which have given mixed results, PEMBRO-RT being positive and others negative. The term is linked to the pairing Radiotherapy + immunotherapy, to Lattice and GRID radiotherapy, In situ vaccination and Histotripsy as an immune primer, and to an idea on turning one tumour into a vaccine for all the others.", wikipedia: W("Abscopal_effect"), technologies: ["sbrt", "checkpoint-inhibitor"], pathways: ["cgas-sting"] }),
  t({ id: "immunogenic-cell-death", name: "Immunogenic cell death", category: "Immunology", tldr: "Immunogenic cell death is a way of dying that alerts the immune system, unlike quiet apoptosis.", summary: "Immunogenic cell death is a way for a cell to die that alerts the immune system, in contrast to quiet apoptosis. It is marked by calreticulin exposure, release of ATP and HMGB1, and type I interferon, and it can be induced by anthracyclines, oxaliplatin, radiation, some ADC payloads, oncolytic viruses and photoimmunotherapy. This is the basis for synergy between chemotherapy and immunotherapy and between ADCs and immunotherapy. The term is linked to the Antibody-drug conjugate (ADC), Oncolytic viruses and Photoimmunotherapy & photodynamic therapy technologies and is cited by In situ vaccination, Histotripsy as an immune primer, Electrochemotherapy, the cGAS-STING pathway, the terms Apoptosis and Necrosis, Laurence Zitvogel and the bottleneck on cold tumours.", wikipedia: W("Immunogenic_cell_death"), technologies: ["adc", "oncolytic-virus", "photoimmunotherapy"] }),
  t({ id: "adcc", name: "ADCC (antibody-dependent cellular cytotoxicity)", category: "Immunology", tldr: "In ADCC, an antibody flags a cell, and NK cells recognise the flag and kill it.", summary: "ADCC, antibody-dependent cellular cytotoxicity, is the process in which an antibody flags a cell and NK cells recognise the flag and kill it. It is mediated by the interaction between the antibody Fc region and FcγRIIIa (CD16) on the NK cell, and it can be enhanced by afucosylating the antibody, as in obinutuzumab, margetuximab and belantamab. ADCC contributes to the activity of trastuzumab, rituximab and cetuximab, and the mechanism belongs to the Monoclonal antibodies technology entry. Drug records that cite it include Margetuximab, Zolbetuximab, Obinutuzumab, Rituximab, Tafasitamab, Daratumumab, Mogamulizumab, Elotuzumab and Dinutuximab (ch14.18) / dinutuximab beta, and it is referenced by the Gastric & gastro-oesophageal junction cancer and Neuroblastoma (paediatric) entries.", wikipedia: W("Antibody-dependent_cellular_cytotoxicity"), technologies: ["monoclonal-antibody"] }),
  t({ id: "fc-effector", wikipedia: W("Fragment_crystallizable_region"), name: "Fc engineering / effector function", category: "Immunology", tldr: "Tweaking the antibody's tail to make it recruit immune cells more strongly, or not at all.", summary: "Fc engineering means tweaking the antibody's tail, the Fc region, so that it recruits immune cells more strongly, or not at all. Afucosylation and Fc mutations enhance ADCC, whereas Fc-silencing through an IgG4 backbone or LALA mutations prevents unwanted immune activation in checkpoint inhibitors and T-cell engagers, and FcRn-binding mutations extend half-life. The term is linked to the Monoclonal antibodies and Bispecific antibodies technologies and to the terms Antibody, NK cell and Half-life. It is cited by the drug records for Margetuximab, Tislelizumab and Mogamulizumab, by the pathways on myeloid suppression, complement in cancer and NK-cell recognition, and by an idea on bispecific antibodies that engage macrophages instead of T cells.", technologies: ["monoclonal-antibody", "bispecific-antibody"] }),

  // ---- Clinical / regulatory ----
  t({ id: "oligometastatic", links: [{ label: "NCI Dictionary of Cancer Terms: oligometastasis", url: "https://www.cancer.gov/publications/dictionaries/cancer-terms/def/oligometastasis" }, { label: "Lievens et al., Defining oligometastatic disease from a radiation oncology perspective: an ESTRO-ASTRO consensus (Radiotherapy and Oncology 2020)", url: "https://doi.org/10.1016/j.radonc.2020.04.003" }], name: "Oligometastatic disease", category: "Clinical", tldr: "Cancer that has spread to only a few places, which may still be curable by treating each spot.", summary: "Oligometastatic disease is cancer that has spread to only a few sites, usually no more than three to five metastases, and may still be curable if each spot is treated. The SABR-COMET trial supported metastasis-directed SBRT / SABR (stereotactic radiotherapy), and the ESTRO/EORTC classification distinguishes synchronous, oligorecurrent and oligoprogressive disease, the last covered by the related term Oligoprogression. PSMA PET has expanded detection of this state in Prostate cancer, and the term is also referenced by the Renal cell carcinoma entry and the bottleneck on metastasis biology. Ideas building on it include PSMA-PET-guided metastasis-directed therapy as a curative strategy and a test to tell true oligometastatic disease from hidden widespread spread.", technologies: ["sbrt", "psma-pet"] }),
  t({ id: "neoadjuvant-adjuvant", aka: ["pre-operative", "preoperative", "post-operative", "postoperative", "post-surgical"], name: "Neoadjuvant / adjuvant / perioperative", category: "Clinical", tldr: "Neoadjuvant therapy is treatment given before surgery, adjuvant therapy is treatment given after it, and perioperative therapy is both. Neoadjuvant treatment shrinks tumours and shows whether the drug works in the living patient; adjuvant treatment aims to kill microscopic disease left behind.", summary: "Neoadjuvant, adjuvant and perioperative therapy mean treatment given before surgery, after surgery, or both; pre-operative and post-operative are the everyday equivalents. Neoadjuvant treatment shrinks tumours, tests drug sensitivity in the living patient through pathologic complete response and can allow surgery to be de-escalated, while adjuvant treatment aims to kill micrometastases. Immunotherapy appears to work better neoadjuvantly, as NADINA and CheckMate 816 suggested, because the primary tumour is still present to supply antigen. The term is anchored to KEYNOTE-522 and referenced by KEYNOTE-671 and SWOG S1801, by the Colorectal, Gastric, Oesophageal, Bladder & urothelial and Head and neck cancer entries, and by the related term Major pathological response (MPR).", wikipedia: W("Neoadjuvant_therapy"), trials: ["keynote-522"] }),
  t({ id: "first-line", links: [{ label: "NCI Dictionary of Cancer Terms: first-line therapy", url: "https://www.cancer.gov/publications/dictionaries/cancer-terms/def/first-line-therapy" }], aka: ["first-line", "second-line", "third-line", "later-line", "later lines", "1L", "2L", "3L", "first line", "second line", "third line", "line of therapy", "front-line", "frontline", "previously untreated", "prior lines", "treatment-naive"], name: "Lines of therapy", category: "Clinical", tldr: "First-line is the first treatment for advanced cancer; second-line is what comes after it fails, and so on.", summary: "Lines of therapy number the successive treatments a patient with advanced cancer receives: first-line is the initial treatment, second-line follows when it fails, and so on, with aliases such as 1L, 2L, front-line and treatment-naive. Drugs are usually approved first in later lines, where control arms are weak, and then move earlier, and each shift to an earlier line reshapes the entire sequence, as happened with ADCs in TNBC in 2026. The concept is central to Project FrontRunner and to the bottlenecks on too many combinations to test, fragmented care and incentives that reward me-too drugs. It also frames the DESTINY-Breast06, FLAURA, MARIPOSA, KEYNOTE-189, HARMONi-2 and NAPOLI-3 papers and ideas on pathology-triggered trial referral and reflex genomic profiling at diagnosis." }),
  t({ id: "standard-of-care", aka: ["SoC", "standard-of-care", "standard therapy", "standard therapies", "standard treatment", "standard treatments", "standard care", "standard chemotherapy", "standard regimen", "current standard", "guideline-recommended", "guideline-concordant"], name: "Standard of care", category: "Clinical", tldr: "The standard of care is the treatment that guidelines and experts currently consider the best-proven option.", summary: "The standard of care is the treatment that guidelines and expert consensus currently regard as the best-proven option; SoC, standard therapy, standard regimen and guideline-concordant care are its aliases. It is defined by NCCN, ESMO and ASCO guidelines on the basis of randomised evidence, shifts with each positive phase 3 trial, and varies by region according to approvals and reimbursement. The term is linked to the NCCN Guidelines collection, the National Comprehensive Cancer Network (NCCN), the NCCN Compendium and Nathan Cherny. It runs through the bottlenecks on slow trial enrolment, regulatory divergence, prices and value, fragmented care, slow knowledge diffusion and misaligned incentives, and it underpins the idea that sponsors must justify every exclusion criterion.", wikipedia: W("Standard_of_care") }),
  t({ id: "accelerated-approval", aka: ["accelerated approvals", "accelerated-approval", "Project Confirm"], name: "Accelerated approval", category: "Regulatory", tldr: "FDA approval based on early evidence (like tumour shrinkage) on condition that a confirmatory trial follows.", summary: "Accelerated approval is the FDA route that grants approval on early evidence such as tumour shrinkage, measured by surrogate endpoints like ORR or pCR, on condition that a confirmatory trial follows. Approvals are withdrawn when confirmation fails, as with atezolizumab in TNBC after IMpassion131, belantamab in 2022 and sacituzumab in urothelial cancer, and Project Confirm and the 2023 FDORA reforms tightened the requirements. The term is referenced by the Glioma & glioblastoma entry, the drug records for Dordaviprone and Melphalan flufenamide, Project FrontRunner and Real-Time Oncology Review (RTOR). It features in the bottlenecks on trial design, regulatory divergence, prices and value and misaligned incentives, and in an idea on making post-progression sampling a condition of approval.", wikipedia: W("Accelerated_approval_(FDA)") }),
  t({ id: "breakthrough-designation", wikipedia: "https://en.wikipedia.org/wiki/Breakthrough_therapy", name: "Breakthrough Therapy / Priority Review / Priority Voucher", category: "Regulatory", tldr: "Breakthrough Therapy, Priority Review and the Priority Voucher are FDA fast lanes for drugs that look substantially better than existing options.", summary: "Breakthrough Therapy, Priority Review and the Priority Voucher are the FDA's fast lanes for drugs that appear substantially better than existing options. Breakthrough Therapy, created in 2012, provides intensive regulatory guidance; Priority Review shortens the review clock to six months; and the Commissioner's National Priority Voucher pilot launched in 2025 promises reviews of one to two months for selected products, with Sacituzumab tirumotecan receiving one in July 2026. These pathways sit alongside Real-Time Oncology Review (RTOR), Fast Track and RMAT designations and Orphan drug designation under the FDA Oncology Center of Excellence. The term appears in the bottleneck on regulatory divergence and in an idea on transferable priority vouchers for first-in-class drugs.", drugs: ["sacituzumab-tirumotecan"] }),
  t({ id: "companion-diagnostic-term", wikipedia: "https://en.wikipedia.org/wiki/Companion_diagnostic", name: "Companion diagnostic", category: "Regulatory", tldr: "A companion diagnostic is a test the FDA requires before a particular drug can be prescribed.", summary: "A companion diagnostic is a test that the FDA requires before a particular drug can be prescribed, tying the medicine to the assay that identifies who should receive it. Examples include the 22C3 PD-L1 assay for pembrolizumab, FoundationOne CDx for many targeted drugs and myChoice CDx for niraparib and olaparib; the fuller account is in the Companion diagnostics technology entry. The term features in the bottlenecks on unvalidated biomarkers, fragmented care and slow knowledge diffusion, and in the LUNGevity Foundation collection. Ideas that address it include mutual recognition of companion diagnostic approvals between regulators, a reliance pathway so the test arrives with the drug, locking the biomarker cut-off before phase 3 and a fund for prospective validation of academic biomarkers.", technologies: ["companion-diagnostic"] }),
  t({ id: "tumour-agnostic", name: "Tumour-agnostic (tissue-agnostic) approval", category: "Regulatory", tldr: "A tumour-agnostic approval lets a drug be used for any cancer carrying a specific molecular feature, regardless of where it started.", summary: "A tumour-agnostic, or tissue-agnostic, approval allows a drug to be used for any cancer carrying a specific molecular feature, regardless of the organ in which it started. Examples are Pembrolizumab for MSI-H disease in 2017 and TMB-high disease in 2020, larotrectinib, entrectinib and repotrectinib for NTRK fusions, Dabrafenib + trametinib for BRAF V600E, Selpercatinib for RET, and Trastuzumab deruxtecan for HER2 IHC 3+ tumours in 2024. Such approvals rest on basket trials and broad genomic testing, which is why DESTINY-PanTumor02 and DESTINY-CRC02 are linked. The term is referenced by the Non-small-cell lung cancer, Colorectal, Biliary tract, Endometrial and Cervical cancer entries and by the bottleneck on rare and paediatric cancers without markets.", wikipedia: W("Tissue-agnostic_drug"), drugs: ["pembrolizumab", "selpercatinib", "trastuzumab-deruxtecan"] }),
  t({ id: "basket-umbrella-platform", name: "Basket, umbrella, and platform trials", category: "Trials", tldr: "Trial designs that test one drug across several cancers sharing a mutation (basket, such as NCI-MATCH), several drugs each matched to a biomarker within one cancer (umbrella, such as Lung-MAP), or keep adding and dropping arms over time (platform, such as I-SPY 2). Basket results underpin tumour-agnostic approvals.", summary: "Basket, umbrella and platform trials are designs that respectively test one drug across several cancers, several drugs within one cancer, or keep adding and dropping arms over time. Basket trials such as NCI-MATCH and TAPUR enable tumour-agnostic approvals; umbrella trials such as Lung-MAP allow efficient biomarker-driven testing; and platform trials such as I-SPY 2 in breast cancer randomise adaptively, graduating drugs on predicted pCR. The term is referenced by the STAMPEDE and myeloMATCH trials, by the technologies Digital twins and virtual control arms and N-of-1 and rapid platform trials, and by Nicholas James, Zhi-Ming Shao, Angela DeMichele and Laura J. Esserman. It addresses the bottlenecks on rare cancers without markets, slow trial enrolment and trial design and cost.", wikipedia: W("Basket_trial"), aka: ["basket trial", "basket trials", "umbrella trial", "umbrella trials", "platform trial", "platform trials", "master protocol trial", "multi-arm multi-stage", "MAMS", "shared control arm", "common control arm", "perpetual trial"], related: ["basket-trial", "umbrella-trial", "seamless-adaptive", "response-adaptive-randomisation", "tumour-agnostic", "single-arm", "trial-protocol", "master-protocol"], trials: ["navigate", "roar-atc", "stampede", "myelomatch", "pediatric-match"] }),
  t({ id: "real-world-evidence", name: "Real-world evidence", category: "Trials", tldr: "Data from routine care rather than clinical trials, used to check whether results hold outside the trial population.", summary: "Real-world evidence is data drawn from routine care rather than from clinical trials, used to check whether trial results hold in the broader population. Sources include the Flatiron and Foundation Medicine clinico-genomic database, Tempus, registries and claims. It is used to build external control arms, support label expansions and detect under-performance in patients who are older or sicker than those trials enrolled. The term is linked to OMOP common data model and OHDSI, to Digital twins and virtual control arms and Systematic drug repurposing, to the AACR Project GENIE collection and to Karolinska University Hospital and UNICANCER, and it features in the bottlenecks on trial design and cost, data silos and weak real-world evidence and registries.", wikipedia: W("Real_world_evidence"), links: [{ label: "Wikipedia", url: W("Real_world_evidence") }, { label: "FDA real-world evidence programme", url: "https://www.fda.gov/science-research/science-and-research-special-topics/real-world-evidence" }], aka: ["RWE", "real world evidence", "real-world data", "RWD", "real-world study", "real-world studies", "real-world outcomes", "observational study", "observational studies", "target trial emulation", "electronic health records", "claims data", "clinico-genomic database"], related: ["external-control-arm", "pragmatic-trial", "registry-based-trial", "randomised-trial", "hta", "trial-failure-modes", "decentralised-trial"], trials: ["pathfinder-2", "l-mind", "nmtrc003", "circulate-japan"] }),
  t({ id: "theranostics", aka: ["theranostic"], name: "Theranostics", category: "Radiopharma", tldr: "Using the same targeting molecule for a diagnostic scan and a therapy, so you treat exactly what you can see.", summary: "Theranostics uses the same targeting molecule for a diagnostic scan and for therapy, so clinicians treat exactly what they can see. The established pairs are gallium-68 or fluorine-18 PSMA imaging with lutetium-177 or actinium-225 PSMA therapy, gallium-68 DOTATATE with lutetium-177 DOTATATE, and iodine-123 with iodine-131, and one chemistry thereby enables patient selection, dosimetry and response assessment. The concept links the Radioligand therapy (beta emitters), Targeted alpha therapy and PSMA PET technologies with Somatostatin receptor PET, Radioiodine therapy and the pairings PSMA PET to PSMA radioligand therapy and SSTR PET to PRRT. It is referenced by the Prostate cancer, Thyroid cancer and Neuroendocrine tumours entries and by Clarity Pharmaceuticals.", wikipedia: W("Theranostics"), technologies: ["radioligand-therapy", "psma-pet", "targeted-alpha-therapy"] }),
  t({ id: "alpha-vs-beta", wikipedia: W("Targeted_alpha-particle_therapy"), name: "Alpha vs beta emitters", category: "Radiopharma", tldr: "Beta particles (lutetium-177) travel millimetres and are good for bulky disease; alpha particles (actinium-225) travel a few cells' width and kill with far higher energy.", summary: "Beta and alpha emitters are the two kinds of particle used in radioligand therapy. Beta particles from lutetium-177 have low linear energy transfer and a range of 1 to 10 mm, so their crossfire helps in heterogeneous bulky tumours at the cost of marrow toxicity. Alpha particles from actinium-225 have very high linear energy transfer, around 100 keV per micrometre, travel only 50 to 100 micrometres and cause oxygen-independent DNA breaks, though daughter recoil redistributes dose and actinium-225 supply is the bottleneck. The distinction underlies the Radioligand therapy (beta emitters) and Targeted alpha therapy technologies and the pairing Beta radioligand to alpha radioligand, and it is referenced by Radium-223 dichloride and the Neuroendocrine tumours entry.", technologies: ["radioligand-therapy", "targeted-alpha-therapy"] }),
  t({ id: "dosimetry", wikipedia: "https://en.wikipedia.org/wiki/Dosimetry", name: "Dosimetry", category: "Radiopharma", tldr: "Measuring how much radiation dose each organ and tumour actually received from a radioactive drug.", summary: "Dosimetry is the measurement of how much radiation dose each organ and each tumour actually received from a radioactive drug. It relies on post-therapy SPECT/CT imaging at several time points and enables personalised activity prescription instead of fixed doses, and regulators and payers increasingly require it. The term is linked to the SPECT & bone scan and Radioligand therapy (beta emitters) technologies and to Radioembolisation (TARE / SIRT, yttrium-90), Auger-electron therapy and Total-body PET for screening. It is referenced by the Hepatocellular carcinoma and Neuroendocrine tumours entries, the radiopharmaceutical roadmap and the bottleneck on wrong doses, and by ideas on dosimetry-personalised PRRT instead of four fixed cycles and total-body PET for personalised radioligand dosing.", technologies: ["spect", "radioligand-therapy"] }),
  t({ id: "germline-vs-somatic", aka: ["germline", "somatic", "inherited mutations", "tumour-normal"], name: "Germline vs somatic mutations", category: "Genomics", tldr: "Germline mutations are inherited and in every cell; somatic mutations arise in the tumour only.", summary: "Germline mutations are inherited and present in every cell of the body, whereas somatic mutations arise only in the tumour. Germline changes in BRCA, the Lynch syndrome genes or TP53 in Li-Fraumeni syndrome shape cancer risk and affect family members, while somatic mutations are what drive the tumour itself. Tumour-only sequencing can fail to tell the two apart, so paired tumour-normal sequencing is preferred. The term is linked to Germline (hereditary) testing, Lynch syndrome and the ClinVar collection, and it is referenced by the Wilms tumour and Retinoblastoma entries, by Mary-Claire King and Angelina Jolie, by the bottleneck on unidentified inherited risk, and by ideas on reflex germline testing and population germline screening with cascade testing.", wikipedia: W("Germline_mutation"), technologies: ["germline-testing"] }),
  t({ id: "tnm-staging", aka: ["TNM", "T stage", "N stage", "T1a", "T1b", "T1c", "pT2", "T1-2", "T3-4", "N2-3", "M0 disease", "clinical stage"], name: "TNM staging", category: "Clinical", tldr: "TNM staging is the universal system describing tumour size (T), lymph node spread (N), and distant metastasis (M).", summary: "TNM staging is the universal system for describing a cancer by tumour size and extent (T), lymph node spread (N) and distant metastasis (M), with aliases such as T stage, N stage, pT2 and clinical stage. The current scheme is the AJCC/UICC 8th edition, and it increasingly incorporates biomarkers, so that breast prognostic stage includes grade, ER, PR and HER2 status. The resulting stage I to IV groups drive treatment intent. The term connects to the related terms Stage, Primary tumour, Lymph node, Lymph node status, Carcinoma in situ (CIS), Breslow thickness and Disease-specific staging and risk systems, and it is referenced by the Head and neck squamous cell carcinoma entry, the Union for International Cancer Control and an idea for a live national dashboard of stage at diagnosis.", wikipedia: W("TNM_staging_system") }),
  t({ id: "cold-vs-hot", wikipedia: W("Tumor_microenvironment"), links: [{ label: "NCI Dictionary of Cancer Terms: hot tumor", url: "https://www.cancer.gov/publications/dictionaries/cancer-terms/def/hot-tumor" }], name: "Hot vs cold tumours", category: "Immunology", tldr: "'Hot' tumours are full of immune cells and respond to immunotherapy; 'cold' tumours have kept the immune system out.", summary: "Hot tumours are full of immune cells and tend to respond to immunotherapy, whereas cold tumours have kept the immune system out. Immunologists distinguish inflamed tumours, immune-excluded tumours in which T cells are held at the margin by TGF-β and stroma, and immune deserts. Pancreatic cancer, prostate cancer, glioblastoma and most HR-positive breast cancers are cold, and turning cold tumours hot is the goal of radiation, vaccines, ISACs, STING agonists and oncolytic viruses. The term is linked to the Immune checkpoint inhibitors, STING & innate immune agonists and Oncolytic viruses technologies and to Desmoplasia (tumour stroma), and it is referenced by the Pancreatic ductal adenocarcinoma and Glioma & glioblastoma entries, Miriam Merad and the bottleneck on cold tumours.", technologies: ["checkpoint-inhibitor", "sting-agonist", "oncolytic-virus"] }),
  t({ id: "adc-sequencing", wikipedia: W("Antibody-drug_conjugate"), name: "ADC sequencing", category: "ADC", tldr: "The open question of whether a second ADC works after the first one fails, especially when both carry the same type of payload.", summary: "ADC sequencing is the open question of whether a second antibody-drug conjugate works after the first one fails, especially when both carry the same class of payload. Retrospective series including SATEEN, BRE-354 and data at ESMO Breast 2026 show reduced efficacy when a second TOP1-payload ADC follows immediately after the first; proposed mechanisms are SLFN11 loss, TOP1 mutations, efflux and antigen downregulation. Prospective trials such as TRADE-DXd are under way. The term is attached to Triple-negative breast cancer (TNBC) and HR-positive / HER2-negative breast cancer and to the Antibody-drug conjugate (ADC) technology, and it is referenced by Mersana Therapeutics, the pairing cautioning against TOP1 ADC after TOP1 ADC and the idea of payload-class switching.", technologies: ["adc", "topoisomerase-inhibitors"], cancers: ["tnbc", "breast-hr-positive"] }),
];
